import yaml
with open('/home/ubuntu/.agent-ml-research-idea_gen_0513_2/projects/recursive_gen_depth_est/paper_provenance.yaml') as f:
    prov = yaml.safe_load(f)

for section in ['claims', 'tables', 'figures']:
    for item in prov.get(section, []):
        if item.get('deprecated', False):
            continue
        ev = item.get('evidence', [])
        if not ev or (isinstance(ev, list) and len(ev) == 0):
            print(f\"{item['id']} [{item.get('location',{}).get('section','?')}]: {str(item.get('text',''))[:120]}\")
        elif isinstance(ev, str):
            # string format evidence - might be tier3
            print(f\"{item['id']} [{item.get('location',{}).get('section','?')}] (str-evidence): {str(item.get('text',''))[:120]}\")
"
